Perhatikan program berikut: {
ubah adalah fungsi yang menerima masukan integer i dengan rumus:
ubah(1) = 'A'; ubah(2) = 'B'; ubah(3) = 'C', dst.
}
var
kalimat : array[1..10000] of string;
hitung : integer;
procedure berulang(idx,n: integer; kata:string);
var
i:integer;
begin
 if (idx = n) then
 begin
 hitung := hitung+1;
