Perhatikan program berikut: var
lolo: array[0..10] of integer = (1,0,10,3,4,6,-1,14,-10,25,1);

procedure tukar(var a,b: integer);
var
 c: integer;
begin
 c:=a;
 a:=b;
 b:=c;
end;

procedure lele(lili,lala: integer);
var
 i,a,e : integer;
begin
 i := lili;
 a := lala;
 e := (i+a) div 2;
 while (i<a) do
 begin
 while lolo[i] <= lolo[e] do
 i:=i+1;
 while lolo[a] >= lolo[e] do
 a:=a-1;
 if (i<a) then
 begin
 tukar(lolo[i],lolo[a]);
 end;
 i:=i+1;
 a:=a-1;
 end;
 if lili < a then lele(lili,e);
 if i < lala then lele(e,lala);
end;

